class Solution { fun findCrossingTime(n:Int,k:Int,time:Array<IntArray>):Int{val waiting=Comparator<Int>{a,b->val first=time[a][0]+time[a][2];val second=time[b][0]+time[b][2];if(first!=second)second-first else b-a};val waitLeft=java.util.PriorityQueue(waiting);val waitRight=java.util.PriorityQueue(waiting);val byTime=compareBy<LongArray>{it[0]};val workLeft=java.util.PriorityQueue(byTime);val workRight=java.util.PriorityQueue(byTime);for(worker in 0 until k)waitLeft.offer(worker);var current=0L;var boxes=n;while(boxes>0||waitRight.isNotEmpty()||workRight.isNotEmpty()){while(workLeft.isNotEmpty()&&workLeft.peek()[0]<=current)waitLeft.offer(workLeft.poll()[1].toInt());while(workRight.isNotEmpty()&&workRight.peek()[0]<=current)waitRight.offer(workRight.poll()[1].toInt());if(waitRight.isNotEmpty()){val worker=waitRight.poll();current+=time[worker][2];workLeft.offer(longArrayOf(current+time[worker][3],worker.toLong()))}else if(boxes>0&&waitLeft.isNotEmpty()){val worker=waitLeft.poll();current+=time[worker][0];boxes--;workRight.offer(longArrayOf(current+time[worker][1],worker.toLong()))}else{var next=Long.MAX_VALUE;if(workLeft.isNotEmpty())next=minOf(next,workLeft.peek()[0]);if(workRight.isNotEmpty())next=minOf(next,workRight.peek()[0]);current=maxOf(current,next)}};return current.toInt()} }
